table = {
 ('E','id'): ('T','E1'), ('E','('): ('T','E1'),
 ('E1','+'): ('+','T','E1'), ('E1',')'): (), ('E1','$'): (),
 ('T','id'): ('F','T1'), ('T','('): ('F','T1'),
 ('T1','+'): (), ('T1','*'): ('*','F','T1'), ('T1',')'): (), ('T1','$'): (),
 ('F','id'): ('id',), ('F','('): ('(','E',')'),
}
nonterms = {'E','E1','T','T1','F'}
follow = {'E':{')','$'}, 'E1':{')','$'}, 'T':{'+',')','$'}, 'T1':{'+',')','$'}, 'F':{'+','*',')','$'}}
stack = ['$','E']
tokens = ['id','+','*','id','$']
i = 0; errors = 0; skipped = 0; guard = 0
while stack and guard < 1000:
    guard += 1
    X = stack[-1]; a = tokens[i]
    if X == a:
        stack.pop(); i += 1
    elif X in nonterms:
        rule = table.get((X,a))
        if rule is None:
            errors += 1
            if a in follow[X]:
                stack.pop()
            else:
                i += 1; skipped += 1
        else:
            stack.pop()
            for s in reversed(rule):
                stack.append(s)
    else:
        break
print(errors)
print(skipped)
